_install('imtree', '"""Image tree (srhm.tex section 10): the tied structured kernel on the thumbnail pyramid, with hidden\ncontext types.  Exact sum-product, grid-local generalized EM, zero labels.\n\nRepresentation (exact, invertible).  An image of side 2^(L+1) is a quadtree of height L.  The node at\nheight c owns a 2^(c+1)-square region; its STATE is (t, h): t = the 2x2x3 block-average thumbnail of its\nregion (observed: parent-determined, Thm mng(4)), h in {0..H-1} a hidden context type (Thm mng(1)-(3)).\nA child at position i (0..3 = TL,TR,BL,BR) has mean colour t_parent[i]; what it adds is its orthonormal\nHaar detail delta in R^9.  So the image <-> (root thumbnail, all details), and\n    log p(y) = log p(t_R) + sum_children [ log p(delta) ] - n_children * 3 log 2.\n\nTied kernel (same at every height; `untied=True` gives every parent height its own copy; `cstar=c` unties\nonly the parents at heights >= c, the semantic top ST(H, c*) of srhm.tex Def. semtop):\n    h\'_i | h         ~ T_i[h, h\']\n    delta_i | t, h\'  ~ N( A_{i,h\'} g_i(t) + b_{i,h\'},  (U_{i,h\'}^T U_{i,h\'})^{-1} ),\n    g_i(t) = tanh(W_i f(t) + c_i)          (the nonlinear structured part: a small net in leaf coordinates)\nRoot:  h_R ~ pi,  t_R | h_R ~ N(m_h, (V_h^T V_h)^{-1}).\nLeaves (height 0, 2x2 pixel patches) are generated exactly like every other child (design rule, Q4).\nLabel leaf (C > 0): y | h_R ~ l(y | h_R), a fifth child of the root; observed on labelled images (y >= 0),\nsummed out on the others (y = -1).  Learning is the same generalized EM on the joint likelihood.\n"""\nimport math\nimport numpy as np\nimport torch\n\nLOG2 = math.log(2.0)\nULMAX, VLMAX = math.log(2000.0), math.log(1000.0)   # noise floors (sd >= 5e-4, 1e-3): ML for\n# mixtures is unbounded without a floor; dequantization noise alone has sd 1.1e-3 per Haar coefficient.\n\n\n# ---------------------------------------------------------------- pyramid <-> image\ndef morton(g):\n    """Permutation of a g x g grid (row-major index) into quadtree (Morton) order, row bit high."""\n    r, c = np.meshgrid(np.arange(g), np.arange(g), indexing="ij")\n    k = np.zeros_like(r)\n    for b in range(int(math.log2(g)) if g > 1 else 0):\n        k |= ((r >> b) & 1) << (2 * b + 1)\n        k |= ((c >> b) & 1) << (2 * b)\n    order = np.empty(g * g, dtype=np.int64)\n    order[k.ravel()] = np.arange(g * g)\n    return torch.tensor(order)\n\n\ndef blocks(I):\n    """I (B, 2g, 2g, 3) -> (B, g*g [Morton], 2, 2, 3)"""\n    B, S, _, C = I.shape\n    g = S // 2\n    X = I.reshape(B, g, 2, g, 2, C).permute(0, 1, 3, 2, 4, 5).reshape(B, g * g, 2, 2, C)\n    return X[:, morton(g).to(I.device)]\n\n\ndef haar(bl):\n    a, b, c, d = bl[..., 0, 0, :], bl[..., 0, 1, :], bl[..., 1, 0, :], bl[..., 1, 1, :]\n    return (a + b + c + d) / 4, torch.cat([(a - b + c - d) / 2, (a + b - c - d) / 2, (a - b - c + d) / 2], -1)\n\n\ndef ihaar(m, det):\n    H, V, D = det[..., 0:3], det[..., 3:6], det[..., 6:9]\n    a = m + (H + V + D) / 2; b = m + (-H + V - D) / 2; c = m + (H - V - D) / 2; d = m + (-H - V + D) / 2\n    return torch.stack([torch.stack([a, b], -2), torch.stack([c, d], -2)], -3)\n\n\ndef pyramid(y):\n    """y (B, S, S, 3), S = 2^(L+1) -> dict: tR (B,12); for child height c = 0..L-1:\n    tp[c] (B, n_c, 12) parent thumbnails, det[c] (B, n_c, 9); child k\'s parent is node k//4, position k%4."""\n    B, S = y.shape[0], y.shape[1]\n    L = int(round(math.log2(S))) - 1\n    levels = [y]\n    for _ in range(L):\n        I = levels[-1]\n        levels.append(I.reshape(B, I.shape[1] // 2, 2, I.shape[2] // 2, 2, 3).mean((2, 4)))\n    th = [blocks(I) for I in levels]                     # th[c]: (B, n_c, 2,2,3), node thumbnails at height c\n    out = dict(L=L, tR=th[L].reshape(B, 12), tp={}, det={})\n    for c in range(L):\n        _, det = haar(th[c])\n        out["det"][c] = det\n        out["tp"][c] = th[c + 1].reshape(B, -1, 12).repeat_interleave(4, 1)\n    return out\n\n\ndef unpyramid(tR, dets, L):\n    """Inverse: root thumbnail (B,12) and dets[c] (B, n_c, 9) -> image (B, S, S, 3)."""\n    B = tR.shape[0]\n    th = tR.reshape(B, 1, 2, 2, 3)\n    for c in range(L - 1, -1, -1):\n        means = th.reshape(B, -1, 3)                     # pixel i of parent k -> child 4k+i (Morton)\n        th = ihaar(means, dets[c])                       # (B, n_c, 2, 2, 3)\n    g = int(round(math.sqrt(th.shape[1])))\n    inv = torch.argsort(morton(g).to(th.device))\n    X = th[:, inv].reshape(B, g, g, 2, 2, 3).permute(0, 1, 3, 2, 4, 5)\n    return X.reshape(B, 2 * g, 2 * g, 3)\n\n\n# ---------------------------------------------------------------- model\ndef _tri(n):\n    return torch.tril_indices(n, n, -1)\n\n\nclass ImageTree(torch.nn.Module):\n    def __init__(self, H, L=4, hid=32, untied=False, seed=0, det_sd=0.03, root_sd=0.2, cstar=None, C=0):\n        super().__init__()\n        g = torch.Generator().manual_seed(seed)\n        r = lambda *s, sc=1.0: torch.nn.Parameter(torch.randn(*s, generator=g) * sc)\n        cstar = (1 if untied else L + 1) if cstar is None else cstar\n        assert 1 <= cstar <= L + 1\n        self.H, self.L, self.hid, self.cstar, self.C = H, L, hid, cstar, C\n        self.untied = cstar == 1\n        nl = (1 if cstar > 1 else 0) + (L - cstar + 1)            # shared copy + one per untied height\n        self.nl = nl\n        self.W = r(nl, 4, hid, 12, sc=1.0 / math.sqrt(12))\n        self.cb = r(nl, 4, hid, sc=0.1)\n        self.A = r(nl, 4, H, 9, hid, sc=0.3 * det_sd / math.sqrt(hid))\n        self.b = r(nl, 4, H, 9, sc=0.1 * det_sd)\n        self.Uoff = torch.nn.Parameter(torch.zeros(nl, 4, H, 36))\n        self.Ulog = torch.nn.Parameter(torch.full((nl, 4, H, 9), -math.log(det_sd))\n                                       + 0.7 * torch.randn(nl, 4, H, 1, generator=g))   # types start as scales\n        self.Tlog = torch.nn.Parameter(2.0 * torch.eye(H).expand(nl, 4, H, H).clone()\n                                       + 0.3 * torch.randn(nl, 4, H, H, generator=g))\n        self.pilog = torch.nn.Parameter(torch.zeros(H))\n        self.m = r(H, 12, sc=root_sd); self.m.data += 0.47\n        self.Voff = torch.nn.Parameter(torch.zeros(H, 66))\n        self.Vlog = torch.nn.Parameter(torch.full((H, 12), -math.log(root_sd)))\n        if C > 0:\n            self.ylog = torch.nn.Parameter(torch.zeros(H, C))                    # label kernel, uniform start\n\n    # -- pieces\n    def lvl(self, c):                                    # parameter index for parents at height c+1\n        ph = c + 1\n        if ph < self.cstar:\n            return 0\n        return (1 if self.cstar > 1 else 0) + ph - self.cstar\n\n    def logl(self):\n        return torch.log_softmax(self.ylog, -1)                         # (H, C)\n\n    def label_term(self, y):\n        """(B, H): log l(y|h) for labelled images (y >= 0), 0 for unlabelled (y = -1)."""\n        lab = self.logl()[:, y.clamp(min=0)].T\n        return lab * (y >= 0).to(lab.dtype)[:, None]\n\n    def logT(self, c):\n        return torch.log_softmax(self.Tlog[self.lvl(c)], -1)          # (4, H, H) [i, parent, child]\n\n    def logpi(self):\n        return torch.log_softmax(self.pilog, 0)\n\n    def U(self, c):\n        k = self.lvl(c)\n        U = torch.diag_embed(torch.exp(self.Ulog[k].clamp(max=ULMAX))).clone()          # (4, H, 9, 9), precision Cholesky\n        ti = _tri(9).to(U.device)\n        U[:, :, ti[0], ti[1]] = self.Uoff[k]\n        return U\n\n    def mean(self, c, tp):\n        """tp (B, n, 12) parent thumbnails of children at height c -> means (B, n, H, 9)."""\n        k = self.lvl(c)\n        B, n, _ = tp.shape\n        f = ((tp - 0.47) / 0.25).reshape(B, n // 4, 4, 12)\n        gz = torch.tanh(torch.einsum("ihd,bpid->bpih", self.W[k], f) + self.cb[k])       # (B, n/4, 4, hid)\n        mu = torch.einsum("ixeh,bpih->bpixe", self.A[k], gz) + self.b[k]              # (B, n/4, 4, H, 9)\n        return mu.reshape(B, n, self.H, 9)\n\n    def emis(self, c, tp, det):\n        """log N(det | .) for every type: (B, n, H)."""\n        B, n, _ = tp.shape\n        mu = self.mean(c, tp)\n        U = self.U(c)                                                   # (4, H, 9, 9)\n        res = (det[:, :, None, :] - mu).reshape(B, n // 4, 4, self.H, 9)\n        z = torch.einsum("ixjk,bpixk->bpixj", U, res)\n        ld = self.Ulog[self.lvl(c)].clamp(max=ULMAX)                    # (4, H, 9)  log diag\n        ll = -0.5 * (z ** 2).sum(-1) + ld.sum(-1) - 4.5 * math.log(2 * math.pi)\n        return ll.reshape(B, n, self.H)\n\n    def root_emis(self, tR):\n        V = torch.diag_embed(torch.exp(self.Vlog.clamp(max=VLMAX))).clone()\n        ti = _tri(12).to(V.device); V[:, ti[0], ti[1]] = self.Voff\n        z = torch.einsum("xjk,bxk->bxj", V, tR[:, None, :] - self.m)\n        return -0.5 * (z ** 2).sum(-1) + self.Vlog.clamp(max=VLMAX).sum(-1) - 6 * math.log(2 * math.pi)\n\n    # -- exact sum-product over types\n    def upward(self, P, lls, cmin=0, y=None):\n        """lls[c] (B, n_c, H) emission log-lik.  Truncated at child height cmin (nodes below ignored).\n        Returns a[c] (log up-message incl. own emission), msgs[c] (B, n_c, H) child->parent log messages,\n        root log-message and log Z (B,)."""\n        a, msgs = {}, {}\n        inc = None\n        for c in range(cmin, P["L"]):\n            ac = lls[c] if inc is None else lls[c] + inc\n            a[c] = ac\n            B, n, H = ac.shape\n            mx = ac.max(-1, keepdim=True).values\n            e = torch.exp(ac - mx).reshape(B, n // 4, 4, H)\n            T = torch.exp(self.logT(c))                                # (4, H, H)\n            m = torch.log(torch.einsum("ixy,bpiy->bpix", T, e) + 1e-38) + mx.reshape(B, n // 4, 4, 1)\n            msgs[c] = m.reshape(B, n, H)\n            inc = m.sum(2)                                             # (B, n/4, H) incoming at parents\n        aR = self.root_emis(P["tR"]) + inc[:, 0]\n        if y is not None:\n            aR = aR + self.label_term(y)\n        logZ = torch.logsumexp(self.logpi() + aR, -1)\n        return a, msgs, aR, logZ\n\n    def posteriors(self, P, lls, y=None, pooled=True):\n        """Exact node marginals q[c] (B, n_c, H), root qR (B, H), and pair counts xi[c]: pooled (4, H, H), or\n        per node (B, n_c, H_parent, H_child) if pooled=False.  With y: conditioned on the observed labels."""\n        a, msgs, aR, logZ = self.upward(P, lls, y=y)\n        L = P["L"]\n        qR = torch.softmax(self.logpi() + aR, -1)\n        D_par = (self.logpi() + aR)[:, None, :]                       # parent (down + up) at the root\n        q, xi = {}, {}\n        for c in range(L - 1, -1, -1):\n            B, n, H = a[c].shape\n            full = D_par.repeat_interleave(4, 1)                       # parent\'s total log-belief per child\n            r = full - msgs[c]                                         # exclude this child\'s own message\n            logT = self.logT(c)\n            rm = r.max(-1, keepdim=True).values\n            A = torch.exp(r - rm).reshape(B, n // 4, 4, H)\n            am = a[c].max(-1, keepdim=True).values\n            Bv = torch.exp(a[c] - am).reshape(B, n // 4, 4, H)\n            T = torch.exp(logT)\n            TB = torch.einsum("ixy,bpiy->bpix", T, Bv)                 # (B, n/4, 4, H_parent)\n            Z = (A * TB).sum(-1, keepdim=True)\n            if pooled:\n                xi[c] = T * torch.einsum("bpix,bpiy->ixy", A / Z, Bv)\n            else:\n                xi[c] = (T[None, None] * (A / Z)[..., :, None] * Bv[..., None, :]).reshape(B, n, H, H)\n            down = torch.log(torch.einsum("bpix,ixy->bpiy", A, T) + 1e-38).reshape(B, n, H) + rm\n            tot = down + a[c]\n            q[c] = torch.softmax(tot, -1)\n            D_par = tot\n        return q, qR, xi, logZ\n\n    def logp_image(self, P, lls=None, cmin=0, y=None):\n        """log density of the pyramid truncated at child height cmin (cmin=0: the whole image); with y, the\n        joint log p(image, y) for labelled entries."""\n        if lls is None:\n            lls = {c: self.emis(c, P["tp"][c], P["det"][c]) for c in range(cmin, P["L"])}\n        logZ = self.upward(P, lls, cmin, y=y)[3]\n        nchild = sum(P["det"][c].shape[1] for c in range(cmin, P["L"]))\n        return logZ - nchild * 3 * LOG2\n\n    # -- learning: grid-local statistics only\n    def q_objective(self, P, y=None):\n        """Expected complete-data log-lik under the exact posterior (Fisher identity: its gradient equals\n        the gradient of the marginal log-likelihood).  Returns (-Q per image, log p per image).  With labels y\n        (-1 = unlabelled) the likelihood is the joint one: log p(image, y) where y is observed."""\n        lls = {c: self.emis(c, P["tp"][c], P["det"][c]) for c in range(P["L"])}\n        with torch.no_grad():\n            q, qR, xi, logZ = self.posteriors(P, {c: v.detach() for c, v in lls.items()}, y=y)\n        Q = (qR * (self.logpi() + self.root_emis(P["tR"]))).sum()\n        if y is not None:\n            Q = Q + (qR * self.label_term(y)).sum()\n        for c in range(P["L"]):\n            Q = Q + (q[c] * lls[c]).sum() + (xi[c] * self.logT(c)).sum()\n        B = P["tR"].shape[0]\n        nchild = sum(P["det"][c].shape[1] for c in range(P["L"]))\n        return -Q / B, (logZ - nchild * 3 * LOG2)\n\n    # -- root state for the head\n    @torch.no_grad()\n    def root_state(self, P):\n        lls = {c: self.emis(c, P["tp"][c], P["det"][c]) for c in range(P["L"])}\n        a, msgs, aR, logZ = self.upward(P, lls)\n        return torch.log_softmax(self.logpi() + aR, -1), P["tR"]\n\n    @torch.no_grad()\n    def state_grid(self, P, c):\n        """The state grid G_c (srhm.tex Cor. reach, item 2): thumbnails (B, n_c, 12) of the nodes at height c and\n        the log-messages they receive from their children (B, n_c, H), normalized; 1 <= c <= L-1."""\n        lls = {k: self.emis(k, P["tp"][k], P["det"][k]) for k in range(c)}\n        a, msgs = {}, {}\n        inc = None\n        for k in range(c):\n            ak = lls[k] if inc is None else lls[k] + inc\n            B, n, H = ak.shape\n            mx = ak.max(-1, keepdim=True).values\n            e = torch.exp(ak - mx).reshape(B, n // 4, 4, H)\n            T = torch.exp(self.logT(k))\n            m = torch.log(torch.einsum("ixy,bpiy->bpix", T, e) + 1e-38) + mx.reshape(B, n // 4, 4, 1)\n            inc = m.sum(2)\n        return P["tp"][c - 1][:, ::4], torch.log_softmax(inc, -1)\n\n    def kappa(self):\n        """Birkhoff contraction kappa(T) = tanh(Delta(T)/4) for every stored kernel copy and position: (nl, 4)."""\n        lT = torch.log_softmax(self.Tlog, -1)                          # (nl, 4, H, H) [.., parent, child]\n        # Delta = max over parents a,a\' and children b,b\' of lT[a,b]+lT[a\',b\']-lT[a,b\']-lT[a\',b]\n        r = lT[..., :, None, :] - lT[..., None, :, :]                  # (nl, 4, a, a\', b): lT[a,b]-lT[a\',b]\n        D = (r.max(-1).values + (-r).max(-1).values).flatten(-2).max(-1).values\n        return torch.tanh(D / 4)\n\n    # -- generation: ancestral sampling, top-down\n    @torch.no_grad()\n    def sample(self, B, gen=None):\n        dev = self.m.device\n        H, L = self.H, self.L\n        hR = torch.multinomial(torch.exp(self.logpi()), B, replacement=True, generator=gen)\n        V = torch.diag_embed(torch.exp(self.Vlog.clamp(max=VLMAX))).clone()\n        ti = _tri(12).to(dev); V[:, ti[0], ti[1]] = self.Voff\n        eps = torch.randn(B, 12, 1, device=dev, generator=gen)\n        tR = self.m[hR] + torch.linalg.solve_triangular(V[hR], eps, upper=False).squeeze(-1)\n        th, types, dets = tR.reshape(B, 1, 12), hR.reshape(B, 1), {}\n        for c in range(L - 1, -1, -1):\n            n = th.shape[1] * 4\n            T = torch.exp(self.logT(c))                               # (4, H, H)\n            pos = torch.arange(4, device=dev).repeat(th.shape[1])\n            par = types.repeat_interleave(4, 1)                       # (B, n)\n            probs = T[pos[None, :].expand(B, n), par]                 # (B, n, H)\n            ch = torch.multinomial(probs.reshape(-1, H), 1, generator=gen).reshape(B, n)\n            tp = th.repeat_interleave(4, 1)\n            mu = self.mean(c, tp)                                     # (B, n, H, 9)\n            mu = torch.gather(mu, 2, ch[:, :, None, None].expand(B, n, 1, 9)).squeeze(2)\n            U = self.U(c)[pos[None, :].expand(B, n), ch]              # (B, n, 9, 9)\n            eps = torch.randn(B, n, 9, 1, device=dev, generator=gen)\n            det = mu + torch.linalg.solve_triangular(U, eps, upper=False).squeeze(-1)\n            dets[c] = det\n            means = th.reshape(B, -1, 3)\n            th = ihaar(means, det).reshape(B, n, 12)\n            types = ch\n        return unpyramid(tR, dets, L), dets, tR\n\n\ndef nparams(model):\n    return sum(p.numel() for p in model.parameters())\n')
_install('exp_cifar', '"""CIFAR-10 joint experiment for srhm.tex section 10 (predictions I1-I6 are fixed there before this runs).\n\nOne zero-label model (imtree.ImageTree: tied structured kernel on the thumbnail pyramid, H hidden\ncontext types, exact sum-product, generalized EM = Fisher-identity gradient of grid-local statistics)\nis evaluated three ways:\n  density     test bits/dim, total and per height (truncated pyramids);\n  readout     linear heads on the ROOT state only: (i) the Bayes head P(y|h) learned by EM as a label leaf,\n              (ii) multinomial logistic regression on (log root belief, root thumbnail); P labels;\n  generation  ancestral samples: per-height Haar energy and kurtosis vs the test set; a PNG grid.\n\n  usage:  exp_cifar.py main     -- N = 50000, H in (1, 16, 128) tied, H = 16 untied\n          exp_cifar.py sweep    -- claim 1: H = 16, tied vs untied, N = 64 ... 50000 unlabelled images\n"""\nimport os, sys, io, json, time, math, base64\nimport numpy as np\nimport torch\nsys.path.insert(0, os.path.dirname(os.path.abspath(globals().get("__file__", "./x"))))\nimport imtree as it\n\nDEV = "cuda" if torch.cuda.is_available() else "cpu"\nBUDGET = float(os.environ.get("BUDGET_SECONDS", "1e9")); T0 = time.time()\nLN2 = math.log(2.0)\n\n\ndef log(**k):\n    k["t"] = round(time.time() - T0, 1); print(json.dumps(k), flush=True)\n\n\ndef left():\n    return BUDGET - (time.time() - T0)\n\n\n# ------------------------------------------------------------------ data\ndef load_cifar():\n    try:\n        import pandas as pd\n        from PIL import Image\n        base = "https://huggingface.co/datasets/uoft-cs/cifar10/resolve/main/plain_text/"\n        out = []\n        for split in ("train", "test"):\n            df = pd.read_parquet(base + f"{split}-00000-of-00001.parquet")\n            X = np.stack([np.array(Image.open(io.BytesIO(d["bytes"])).convert("RGB")) for d in df["img"]])\n            out.append((X, df["label"].to_numpy()))\n        src = "hf"\n    except Exception as e:                                           # fall back to the Toronto mirror\n        log(event="hf_failed", err=str(e)[:200])\n        import torchvision\n        out = []\n        for tr in (True, False):\n            d = torchvision.datasets.CIFAR10("/content/cifar", train=tr, download=True)\n            out.append((d.data, np.array(d.targets)))\n        src = "torchvision"\n    (Xtr, ytr), (Xte, yte) = out\n    log(event="data", src=src, n_train=len(ytr), n_test=len(yte))\n    t = lambda a: torch.tensor(a, device=DEV)\n    return t(Xtr), t(ytr), t(Xte), t(yte)\n\n\ndef deq(Xu8, gen=None):\n    return (Xu8.float() + torch.rand(Xu8.shape, device=Xu8.device, generator=gen)) / 256.0\n\n\n# ------------------------------------------------------------------ learning (zero labels)\ndef fit(model, X, steps, batch, lr=3e-3, tag=""):\n    opt = torch.optim.Adam(model.parameters(), lr=lr)\n    sched = torch.optim.lr_scheduler.LambdaLR(opt, lambda s: 0.5 * (1 + math.cos(math.pi * min(s / steps, 1.0))))\n    N = X.shape[0]\n    run, t = None, time.time()\n    for s in range(steps):\n        idx = torch.randint(0, N, (batch,), device=DEV) if N > batch else torch.arange(N, device=DEV)\n        negQ, lp = model.q_objective(it.pyramid(deq(X[idx])))\n        opt.zero_grad(); negQ.backward(); opt.step(); sched.step()\n        bpd = float(-lp.mean() / (3072 * LN2) + 8)\n        run = bpd if run is None else 0.98 * run + 0.02 * bpd\n        if s % 500 == 0 or s == steps - 1:\n            log(event="train", tag=tag, step=s, train_bpd=round(run, 4), secs=round(time.time() - t, 1))\n    return model\n\n\ndef timed_steps(model, X, batch, alloc, cap):\n    """Steps that fit in `alloc` seconds (measured on 10 steps), at most cap."""\n    m2 = it.ImageTree(model.H, untied=model.untied, hid=model.hid, seed=99).to(DEV)\n    opt = torch.optim.Adam(m2.parameters(), lr=1e-4)\n    for k in range(12):\n        if k == 2:\n            torch.cuda.synchronize() if DEV == "cuda" else None; t = time.time()\n        idx = torch.randint(0, X.shape[0], (min(batch, X.shape[0]),), device=DEV)\n        negQ, _ = m2.q_objective(it.pyramid(deq(X[idx])))\n        opt.zero_grad(); negQ.backward(); opt.step()\n    torch.cuda.synchronize() if DEV == "cuda" else None\n    tps = (time.time() - t) / 10\n    return int(min(cap, max(200, alloc / tps))), tps\n\n\n# ------------------------------------------------------------------ evaluation\n@torch.no_grad()\ndef eval_density(model, X, bs=500):\n    g = torch.Generator(device=DEV).manual_seed(123)\n    L = model.L\n    tot = torch.zeros(L + 1, dtype=torch.float64, device=DEV)\n    for s in range(0, X.shape[0], bs):\n        P = it.pyramid(deq(X[s:s + bs], g))\n        lls = {c: model.emis(c, P["tp"][c], P["det"][c]) for c in range(L)}\n        B = P["tR"].shape[0]\n        for c in range(L):                                          # Jacobian constant is PER IMAGE\n            tot[c] += model.upward(P, lls, cmin=c)[3].double().sum() - B * sum(\n                P["det"][k].shape[1] for k in range(c, L)) * 3 * LN2\n        tot[L] += torch.logsumexp(model.logpi() + model.root_emis(P["tR"]), -1).double().sum()\n    lp = (tot / X.shape[0]).cpu().numpy()                          # mean log p(levels >= c), c = 0..L\n    n = [4 ** (L - c) for c in range(L)]\n    per = {f"c{c}": round(float(-(lp[c] - lp[c + 1]) / (9 * n[c] * LN2)), 4) for c in range(L)}\n    per["root"] = round(float(-lp[L] / (12 * LN2)), 4)\n    return round(float(-lp[0] / (3072 * LN2) + 8), 4), per, float(lp[0])\n\n\n@torch.no_grad()\ndef root_features(model, X, bs=1000):\n    g = torch.Generator(device=DEV).manual_seed(7)\n    lq, tr = [], []\n    for s in range(0, X.shape[0], bs):\n        a, b = model.root_state(it.pyramid(deq(X[s:s + bs], g)))\n        lq.append(a.clamp(min=-50)); tr.append(b)\n    return torch.cat(lq), torch.cat(tr)\n\n\ndef bayes_head(lq_tr, ytr, lq_te, yte, P, iters=200):\n    """Label leaf of the root: P(y|h) by EM on P labelled images (root model fixed).  Prediction\n    P(y|X) = sum_h beta(h) P(y|h): linear in the root belief (Prop. readout)."""\n    q = torch.exp(lq_tr[:P]); y = ytr[:P]\n    H = q.shape[1]\n    Py = torch.full((H, 10), 0.1, device=DEV)\n    Y = torch.nn.functional.one_hot(y, 10).float()\n    for _ in range(iters):\n        w = q * Py[:, y].T\n        w = w / w.sum(1, keepdim=True).clamp(min=1e-30)\n        Py = (w.T @ Y + 1e-3) / (w.sum(0)[:, None] + 1e-2)\n    pred = (torch.exp(lq_te) @ Py).argmax(1)\n    return float((pred == yte).float().mean())\n\n\ndef logistic_head(F_tr, ytr, F_te, yte, P, steps=600, wd=1e-4):\n    mu, sd = F_tr[:P].mean(0), F_tr[:P].std(0) + 1e-6\n    A, B = (F_tr[:P] - mu) / sd, (F_te - mu) / sd\n    lin = torch.nn.Linear(A.shape[1], 10).to(DEV)\n    opt = torch.optim.Adam(lin.parameters(), lr=1e-2, weight_decay=wd)\n    for _ in range(steps):\n        loss = torch.nn.functional.cross_entropy(lin(A), ytr[:P]); opt.zero_grad(); loss.backward(); opt.step()\n    with torch.no_grad():\n        return float((lin(B).argmax(1) == yte).float().mean())\n\n\ndef detail_stats(dets, L):\n    out = {}\n    for c in range(L):\n        d = dets[c].reshape(-1, 9).double()\n        k = ((d - d.mean(0)) ** 4).mean(0) / d.var(0) ** 2\n        out[f"c{c}"] = dict(energy=round(float((d ** 2).sum(1).mean()), 6), kurt=round(float(k.mean()), 2))\n    return out\n\n\ndef png_grid(x, nrow=10):\n    from PIL import Image\n    x = (x.clamp(0, 1) * 255).round().byte().cpu().numpy()\n    B = x.shape[0]; ncol = int(math.ceil(B / nrow))\n    G = np.full((ncol * 34, nrow * 34, 3), 255, np.uint8)\n    for k in range(B):\n        r, c = divmod(k, nrow)\n        G[r * 34 + 1: r * 34 + 33, c * 34 + 1: c * 34 + 33] = x[k]\n    buf = io.BytesIO(); Image.fromarray(G).save(buf, format="PNG")\n    return base64.b64encode(buf.getvalue()).decode()\n\n\ndef evaluate(model, Xte, yte, Xtr, ytr, tag, full=True):\n    bpd, per, lp = eval_density(model, Xte)\n    res = dict(event="eval", tag=tag, H=model.H, untied=model.untied, nparams=it.nparams(model),\n               test_bpd=bpd, per_height_bits=per, test_logp=round(lp, 2))\n    lq_tr, t_tr = root_features(model, Xtr); lq_te, t_te = root_features(model, Xte)\n    F_tr, F_te = torch.cat([lq_tr, t_tr], 1), torch.cat([lq_te, t_te], 1)\n    Ps = (100, 1000, 10000, 50000) if full else (50000,)\n    res["bayes_head"] = {P: round(bayes_head(lq_tr, ytr, lq_te, yte, P), 4) for P in Ps}\n    res["logistic_head"] = {P: round(logistic_head(F_tr, ytr, F_te, yte, P), 4) for P in Ps}\n    res["root_belief_entropy"] = round(float(-(torch.exp(lq_te) * lq_te).sum(1).mean()), 3)\n    if full:\n        g = torch.Generator(device=DEV).manual_seed(5)\n        dets_s = {c: [] for c in range(model.L)}\n        for _ in range(10):\n            x, d, _ = model.sample(1000, gen=g)\n            for c in range(model.L):\n                dets_s[c].append(d[c])\n        res["sample_stats"] = detail_stats({c: torch.cat(v) for c, v in dets_s.items()}, model.L)\n        res["data_stats"] = detail_stats(it.pyramid(deq(Xte))["det"], model.L)\n        res["png"] = png_grid(model.sample(100, gen=torch.Generator(device=DEV).manual_seed(11))[0])\n    log(**res)\n    return res\n\n\n# ------------------------------------------------------------------ drivers\ndef main(mode):\n    log(event="start", mode=mode, dev=DEV, budget=BUDGET)\n    torch.manual_seed(0)\n    Xtr, ytr, Xte, yte = load_cifar()\n    perm = torch.randperm(Xtr.shape[0], generator=torch.Generator().manual_seed(0)).to(DEV)\n    Xtr, ytr = Xtr[perm], ytr[perm]                                   # fixed random order: label subsets = prefixes\n    if mode == "main":\n        log(event="real_data_png", png=png_grid(deq(Xte[:100]).float()))\n        configs = [(1, False), (16, False), (128, False), (16, True)]\n        for k, (H, untied) in enumerate(configs):\n            model = it.ImageTree(H, untied=untied, seed=0).to(DEV)\n            alloc = (left() - 600) / (len(configs) - k) * 0.75\n            steps, tps = timed_steps(model, Xtr, 128, alloc, 6000)\n            log(event="plan", H=H, untied=untied, steps=steps, secs_per_step=round(tps, 4), nparams=it.nparams(model))\n            fit(model, Xtr, steps, 128, tag=f"H{H}{\'u\' if untied else \'\'}")\n            evaluate(model, Xte, yte, Xtr, ytr, tag=f"H{H}{\'u\' if untied else \'\'}_N50000")\n    elif mode == "sweep":\n        H = 16\n        runs = [(N, s, u) for N in (64, 256, 1024, 4096, 16384, 50000) for s in ((0, 1) if N <= 1024 else (0,))\n                for u in (False, True)]\n        for k, (N, seed, untied) in enumerate(runs):\n            if left() < 300:\n                log(event="budget_stop", remaining=len(runs) - k); break\n            sub = Xtr[seed * 1000: seed * 1000 + N] if N <= 1024 else Xtr[:N]\n            model = it.ImageTree(H, untied=untied, seed=seed).to(DEV)\n            steps = 3000\n            fit(model, sub, steps, min(N, 128), tag=f"N{N}s{seed}{\'u\' if untied else \'\'}")\n            r = evaluate(model, Xte, yte, Xtr, ytr, tag=f"sweep_N{N}_s{seed}{\'u\' if untied else \'\'}", full=False)\n    log(event="done")\n\n\nif __name__ == "__main__":\n    main(sys.argv[1] if len(sys.argv) > 1 else "main")\n')
"""The semantic top on CIFAR-10 (srhm.tex Sec. semtop; predictions S1-S5 are fixed there before `run`).

  usage:  exp_semtop.py cal   -- calibration, run BEFORE the predictions: a zero-label tied IT(16); Birkhoff
                                 contractions kappa of its kernel, label-kernel spreads lambda_y, posterior
                                 certainty eps per height; and the class information in the state grids G_c
                                 (thumbnails + messages from below, Cor. reach item 2), c = 1, 2, 3, and root.
          exp_semtop.py run   -- ST(16, c*) for c* in (5 = tied, 4, 3) and P in (0, 1000, 50000) labelled images
                                 among N = 50000, trained by generalized EM on the joint likelihood.  Density,
                                 Bayes head, logistic head, measured label reach per height against Thm. reach.
"""
import os, sys, math, time, copy
import numpy as np
import torch
sys.path.insert(0, os.path.dirname(os.path.abspath(globals().get("__file__", "./x"))))
import imtree as it
import exp_cifar as ex

DEV, LN2, log, left = ex.DEV, ex.LN2, ex.log, ex.left
H, STEPS, BATCH = 16, int(os.environ.get("SEMTOP_STEPS", "3000")), 128


def fit_joint(model, X, y, P, steps=STEPS, batch=BATCH, lr=3e-3, tag=""):
    """Generalized EM on sum_n log p(X_n) + sum_{n<P} log p(y_n | X_n) (the joint likelihood with the label leaf
    observed on the first P images, summed out on the others).  Uniform minibatches over all N images."""
    opt = torch.optim.Adam(model.parameters(), lr=lr)
    sched = torch.optim.lr_scheduler.LambdaLR(opt, lambda s: 0.5 * (1 + math.cos(math.pi * min(s / steps, 1.0))))
    N = X.shape[0]
    run, t = None, time.time()
    for s in range(steps):
        idx = torch.randint(0, N, (batch,), device=DEV)
        yb = torch.where(idx < P, y[idx], torch.full_like(idx, -1)) if model.C > 0 else None
        negQ, lp = model.q_objective(it.pyramid(ex.deq(X[idx])), y=yb)
        opt.zero_grad(); negQ.backward(); opt.step(); sched.step()
        v = float(-lp.mean() / (3072 * LN2) + 8)
        run = v if run is None else 0.98 * run + 0.02 * v
        if s % 500 == 0 or s == steps - 1:
            log(event="train", tag=tag, step=s, train_joint_bpd=round(run, 4), secs=round(time.time() - t, 1))
    return model


# ------------------------------------------------------------------ calibration helpers
def mlp_head(F_tr, y_tr, F_te, y_te, hidden=512, epochs=int(os.environ.get("SEMTOP_EPOCHS", "40")), wd=5e-4,
             lin=False, nval=5000):
    """Classifier on fixed features; model selection by the best epoch on a held-out part of the training set."""
    mu, sd = F_tr.mean(0), F_tr.std(0) + 1e-6
    A, B = (F_tr - mu) / sd, (F_te - mu) / sd
    nval = min(nval, A.shape[0] // 10)
    Av, yv, At, yt = A[:nval], y_tr[:nval], A[nval:], y_tr[nval:]
    torch.manual_seed(0)
    net = (torch.nn.Linear(A.shape[1], 10) if lin else torch.nn.Sequential(
        torch.nn.Linear(A.shape[1], hidden), torch.nn.ReLU(), torch.nn.Dropout(0.3),
        torch.nn.Linear(hidden, hidden), torch.nn.ReLU(), torch.nn.Dropout(0.3), torch.nn.Linear(hidden, 10))).to(DEV)
    opt = torch.optim.Adam(net.parameters(), lr=1e-3, weight_decay=wd)
    best, best_te = -1, 0
    for ep in range(epochs):
        net.train()
        perm = torch.randperm(At.shape[0], device=DEV)
        for k in range(0, At.shape[0], 256):
            b = perm[k:k + 256]
            loss = torch.nn.functional.cross_entropy(net(At[b]), yt[b]); opt.zero_grad(); loss.backward(); opt.step()
        net.eval()
        with torch.no_grad():
            va = float((net(Av).argmax(1) == yv).float().mean())
            if va > best:
                best, best_te = va, float((net(B).argmax(1) == y_te).float().mean())
    return round(best_te, 4)


@torch.no_grad()
def grids(model, X, c, bs=1000):
    g = torch.Generator(device=DEV).manual_seed(7)
    th, ms = [], []
    for s in range(0, X.shape[0], bs):
        a, b = model.state_grid(it.pyramid(ex.deq(X[s:s + bs], g)), c)
        th.append(a.reshape(a.shape[0], -1)); ms.append(b.clamp(min=-30).reshape(b.shape[0], -1))
    return torch.cat(th), torch.cat(ms)


@torch.no_grad()
def certainty(model, X, bs=500):
    """Mean eps_v = 1 - max_h q_v(h) per height (posterior without label), and root."""
    P = it.pyramid(ex.deq(X[:bs], torch.Generator(device=DEV).manual_seed(3)))
    lls = {c: model.emis(c, P["tp"][c], P["det"][c]) for c in range(model.L)}
    q, qR, _, _ = model.posteriors(P, lls)
    out = {f"c{c}": round(float((1 - q[c].max(-1).values).mean()), 4) for c in range(model.L)}
    out["root"] = round(float((1 - qR.max(-1).values).mean()), 4)
    return out


# ------------------------------------------------------------------ label reach (Thm. reach)
@torch.no_grad()
def reach(model, X, y, bs=500):
    """Measured TV(q^y_v, q_v) and d_H per height (true labels), and the bound of Thm. reach node by node.
    Float64 copy of the model, so that small influences at deep nodes are not rounding noise."""
    model = copy.deepcopy(model).double()
    P = it.pyramid(ex.deq(X[:bs], torch.Generator(device=DEV).manual_seed(4)).double())
    yb = y[:bs]
    lls = {c: model.emis(c, P["tp"][c], P["det"][c]) for c in range(model.L)}
    q0, qR0, _, _ = model.posteriors(P, lls)
    q1, qR1, _, _ = model.posteriors(P, lls, y=yb)
    ll = model.logl()                                                   # (H, C)
    lam = (ll.max(0).values - ll.min(0).values)[yb]                     # (B,)
    kap = model.kappa()                                                 # (nl, 4)
    def dH(p, r):
        d = torch.log(p.clamp(min=1e-300)) - torch.log(r.clamp(min=1e-300))
        return d.max(-1).values - d.min(-1).values
    out = {}
    tvR = 0.5 * (qR1 - qR0).abs().sum(-1)
    out["root"] = dict(tv=round(float(tvR.mean()), 4), dH=round(float(dH(qR1, qR0).mean()), 3),
                       lam=round(float(lam.mean()), 3))
    for c in range(model.L - 1, -1, -1):
        n = q0[c].shape[1]
        k = torch.arange(n, device=DEV)
        prod = torch.ones(n, device=DEV, dtype=torch.float64); idx = k.clone()
        for cc in range(c, model.L):
            prod = prod * kap[model.lvl(cc)][idx % 4]; idx = idx // 4
        D = lam[:, None] * prod[None, :]                                # (B, n)
        eps = 1 - q0[c].max(-1).values
        bound = torch.minimum(torch.tanh(D / 4), eps * torch.exp(D.clamp(max=50)) / (1 - eps).clamp(min=1e-12))
        tv = 0.5 * (q1[c] - q0[c]).abs().sum(-1)
        out[f"c{c}"] = dict(tv=float(f"{float(tv.mean()):.3g}"), tv_max=float(f"{float(tv.max()):.3g}"),
                            dH=float(f"{float(dH(q1[c], q0[c]).mean()):.3g}"),
                            bound=float(f"{float(bound.mean()):.3g}"), D=float(f"{float(D.mean()):.3g}"),
                            viol=int((tv > bound + 1e-6).sum()))
    return out


# ------------------------------------------------------------------ evaluation of a (joint) model
@torch.no_grad()
def joint_bayes_head(model, lq_te, yte):
    return round(float(((torch.exp(lq_te) @ torch.exp(model.logl())).argmax(1) == yte).float().mean()), 4)


def evaluate(model, Xte, yte, Xtr, ytr, tag, P):
    bpd, per, lp = ex.eval_density(model, Xte)
    res = dict(event="eval", tag=tag, cstar=model.cstar, P=P, nparams=it.nparams(model), test_bpd=bpd,
               per_height_bits=per)
    lq_tr, t_tr = ex.root_features(model, Xtr); lq_te, t_te = ex.root_features(model, Xte)
    F_tr, F_te = torch.cat([lq_tr, t_tr], 1), torch.cat([lq_te, t_te], 1)
    if P > 0:
        res["bayes_head_joint"] = joint_bayes_head(model, lq_te, yte)
    res["bayes_head_posthoc"] = {Q: round(ex.bayes_head(lq_tr, ytr, lq_te, yte, Q), 4) for Q in (1000, 50000)}
    res["logistic_head"] = {Q: round(ex.logistic_head(F_tr, ytr, F_te, yte, Q), 4) for Q in (1000, 50000)}
    res["root_belief_entropy"] = round(float(-(torch.exp(lq_te) * lq_te).sum(1).mean()), 3)
    res["kappa"] = [[round(float(v), 4) for v in row] for row in model.kappa()]
    res["certainty_eps"] = certainty(model, Xte)
    if P > 0:
        res["reach"] = reach(model, Xte, yte)
    log(**res)
    return res


def main(mode):
    log(event="start", mode=mode, dev=DEV, budget=ex.BUDGET)
    torch.manual_seed(0)
    Xtr, ytr, Xte, yte = ex.load_cifar()
    perm = torch.randperm(Xtr.shape[0], generator=torch.Generator().manual_seed(0)).to(DEV)
    Xtr, ytr = Xtr[perm], ytr[perm]                                   # fixed random order: labelled = prefix
    if mode == "cal":
        model = it.ImageTree(H, seed=0).to(DEV)
        fit_joint(model, Xtr, ytr, 0, tag="cal_H16_tied")
        bpd, per, _ = ex.eval_density(model, Xte)
        lq_tr, t_tr = ex.root_features(model, Xtr); lq_te, t_te = ex.root_features(model, Xte)
        # label kernel fitted on the frozen root (as in Sec. cifar-res), for lambda_y
        q = torch.exp(lq_tr); Y = torch.nn.functional.one_hot(ytr, 10).float()
        Py = torch.full((H, 10), 0.1, device=DEV)
        for _ in range(200):
            w = q * Py[:, ytr].T; w = w / w.sum(1, keepdim=True).clamp(min=1e-30)
            Py = (w.T @ Y + 1e-3) / (w.sum(0)[:, None] + 1e-2)
        lPy = torch.log(Py / Py.sum(1, keepdim=True))
        lam = (lPy.max(0).values - lPy.min(0).values)
        log(event="cal_model", test_bpd=bpd, per_height_bits=per, kappa=[round(float(v), 4) for v in model.kappa()[0]],
            lambda_y=[round(float(v), 2) for v in lam], certainty_eps=certainty(model, Xte),
            root_entropy=round(float(-(torch.exp(lq_te) * lq_te).sum(1).mean()), 3))
        R_tr, R_te = torch.cat([lq_tr, t_tr], 1), torch.cat([lq_te, t_te], 1)
        log(event="grid", c="root", n_nodes=1,
            thumb=dict(lin=mlp_head(t_tr, ytr, t_te, yte, lin=True), mlp=mlp_head(t_tr, ytr, t_te, yte)),
            state=dict(lin=mlp_head(R_tr, ytr, R_te, yte, lin=True), mlp=mlp_head(R_tr, ytr, R_te, yte)))
        for c in (3, 2, 1):
            th_tr, ms_tr = grids(model, Xtr, c); th_te, ms_te = grids(model, Xte, c)
            S_tr, S_te = torch.cat([th_tr, ms_tr], 1), torch.cat([th_te, ms_te], 1)
            log(event="grid", c=c, n_nodes=4 ** (model.L - c),
                thumb=dict(lin=mlp_head(th_tr, ytr, th_te, yte, lin=True), mlp=mlp_head(th_tr, ytr, th_te, yte)),
                msgs=dict(lin=mlp_head(ms_tr, ytr, ms_te, yte, lin=True), mlp=mlp_head(ms_tr, ytr, ms_te, yte)),
                state=dict(lin=mlp_head(S_tr, ytr, S_te, yte, lin=True), mlp=mlp_head(S_tr, ytr, S_te, yte)))
            del th_tr, ms_tr, S_tr
    elif mode == "run":
        runs = [(cs, P) for cs in (5, 4, 3) for P in (0, 1000, 50000)]
        for k, (cs, P) in enumerate(runs):
            if left() < 400:
                log(event="budget_stop", remaining=len(runs) - k); break
            model = it.ImageTree(H, seed=0, cstar=cs, C=10).to(DEV)
            fit_joint(model, Xtr, ytr, P, tag=f"ST{cs}_P{P}")
            evaluate(model, Xte, yte, Xtr, ytr, tag=f"ST16_c{cs}_P{P}", P=P)
    log(event="done")


if __name__ == "__main__":
    main("cal")
